CREATE TABLE monitoringdevices_backup AS SELECT * FROM monitoringdevices;

DROP TABLE IF EXISTS device_reliability_results;
CREATE TEMP TABLE device_reliability_results AS
SELECT 
    md.mondevref,
    md.calibts,
    md.devacc,
    COALESCE(md.recintmin, 0) AS recintmin,
    md.temppts,
    ROUND(LEAST(md.temppts / 1000.0, 1) * 100, 2) AS fr,
    ROUND(LEAST(COALESCE(md.recintmin, 0) / 100.0, 1) * 100, 2) AS fd,
    ROUND(CASE WHEN md.calibts < CURRENT_DATE - INTERVAL '12 months' THEN 0.5 ELSE 0.1 END * 100, 2) AS fc,
    ROUND(CASE WHEN md.devacc::NUMERIC > 0.3 THEN 0.3 ELSE 0.1 END * 100, 2) AS fb,
    ROUND(100 - (10 * LEAST(md.temppts / 1000.0, 1) * 100 + 5 * LEAST(COALESCE(md.recintmin, 0) / 100.0, 1) * 100 + 3 * CASE WHEN md.calibts < CURRENT_DATE - INTERVAL '12 months' THEN 0.5 ELSE 0.1 END * 100 + 2 * CASE WHEN md.devacc::NUMERIC > 0.3 THEN 0.3 ELSE 0.1 END * 100), 2) AS dlrs,
    NOW() AS analysis_time
FROM monitoringdevices md;

ALTER TABLE monitoringdevices ADD COLUMN dlrs NUMERIC(10,2);
ALTER TABLE monitoringdevices ADD COLUMN analysis_time TIMESTAMP;

UPDATE monitoringdevices md SET calibts = drr.calibts, devacc = drr.devacc, recintmin = drr.recintmin, temppts = drr.temppts, dlrs = drr.dlrs, analysis_time = drr.analysis_time FROM device_reliability_results drr WHERE md.mondevref = drr.mondevref;

SELECT mondevref, calibts, devacc, recintmin, temppts, dlrs, analysis_time FROM monitoringdevices ORDER BY mondevref;

CREATE TABLE monitoringdevices_backup AS SELECT * FROM monitoringdevices;

DROP TABLE IF EXISTS device_reliability_results;
CREATE TEMP TABLE device_reliability_results AS
SELECT 
    mondevref,
    calibts,
    devacc,
    recintmin,
    temppts,
    ROUND(LEAST(temppts::NUMERIC / 1000.0, 1) * 100, 2) AS fr,
    ROUND(LEAST(COALESCE(recintmin, 0)::NUMERIC / 100.0, 1) * 100, 2) AS fd,
    ROUND(CASE WHEN calibts < CURRENT_DATE - INTERVAL '12 months' THEN 50 ELSE 10 END, 2) AS fc,
    ROUND(CASE WHEN COALESCE(NULLIF(devacc, 'None')::NUMERIC, 0) > 0.3 THEN 30 ELSE 10 END, 2) AS fb,
    ROUND(100 - (10 * LEAST(temppts::NUMERIC / 1000.0, 1) + 5 * LEAST(COALESCE(recintmin, 0)::NUMERIC / 100.0, 1) + 3 * CASE WHEN calibts < CURRENT_DATE - INTERVAL '12 months' THEN 50 ELSE 10 END + 2 * CASE WHEN COALESCE(NULLIF(devacc, 'None')::NUMERIC, 0) > 0.3 THEN 30 ELSE 10 END), 2) AS dlrs,
    NOW() AS analysis_time
FROM monitoringdevices;

ALTER TABLE monitoringdevices ADD COLUMN dlrs NUMERIC(10,2);
ALTER TABLE monitoringdevices ADD COLUMN analysis_time TIMESTAMP;

UPDATE monitoringdevices md SET dlrs = drr.dlrs, analysis_time = drr.analysis_time FROM device_reliability_results drr WHERE md.mondevref = drr.mondevref;

SELECT mondevref, calibts, devacc, recintmin, temppts, dlrs, analysis_time FROM monitoringdevices ORDER BY mondevref;
